<?php $pageTitle='Expenses';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';requireRole(['owner','manager']);$db=getDB();$club=$_SESSION['club_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$category=$_POST['category']??'';$amount=filter_var($_POST['amount']??'',FILTER_VALIDATE_FLOAT);$date=$_POST['expense_date']??date('Y-m-d');if(!in_array($category,['electricity','rent','water','salaries','equipment','maintenance','miscellaneous'],true)||$amount===false||$amount<=0){$flash='Enter a valid category and amount.';$error=true;}else{$db->prepare('INSERT INTO expenses(club_id,category,amount,description,expense_date,added_by) VALUES(?,?,?,?,?,?)')->execute([$club,$category,$amount,sanitize($_POST['description']??''),$date,$_SESSION['user_id']]);audit('expense_created','expenses',(int)$db->lastInsertId());$flash='Expense added.';}}$q=$db->prepare("SELECT e.*,u.name user_name FROM expenses e JOIN users u ON u.id=e.added_by WHERE e.club_id=? ORDER BY e.expense_date DESC LIMIT 100");$q->execute([$club]);$rows=$q->fetchAll();$q=$db->prepare("SELECT category,SUM(amount) total FROM expenses WHERE club_id=? AND DATE_FORMAT(expense_date,'%Y-%m')=DATE_FORMAT(CURDATE(),'%Y-%m') GROUP BY category");$q->execute([$club]);$categories=$q->fetchAll();$rev=$db->prepare("SELECT COALESCE(SUM(total_amount),0) FROM sessions WHERE club_id=? AND status='completed' AND DATE_FORMAT(end_time,'%Y-%m')=DATE_FORMAT(CURDATE(),'%Y-%m')");$rev->execute([$club]);$revenue=(float)$rev->fetchColumn();$expenseTotal=array_sum(array_column($categories,'total'));?><div class="flex justify-between"><div><h1 class="text-2xl font-bold">Expenses</h1><p class="text-slate-400 text-sm mt-1">Track operating costs and profitability.</p></div></div><?php if(isset($flash)):?><div class="mt-4 p-3 rounded <?=$error??false?'bg-red-500/15 text-red-300':'bg-green-500/15 text-green-300'?>"><?=sanitize($flash)?></div><?php endif?><form method="post" class="card mt-5"><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><h2 class="font-bold mb-4">Add Expense</h2><div class="grid md:grid-cols-4 gap-3"><div><label class="label">Category</label><select class="input" name="category"><?php foreach(['electricity','rent','water','salaries','equipment','maintenance','miscellaneous'] as $c):?><option><?=$c?></option><?php endforeach?></select></div><div><label class="label">Amount (Rs.)</label><input class="input" name="amount" type="number" min="1" step=".01" required></div><div><label class="label">Date</label><input class="input" name="expense_date" type="date" value="<?=date('Y-m-d')?>"></div><div><label class="label">Description</label><input class="input" name="description" placeholder="Optional note"></div></div><button class="btn-primary mt-4">Add Expense</button></form><div class="grid grid-cols-2 lg:grid-cols-4 gap-4 mt-5"><?php foreach($categories as $c):?><div class="card"><p class="text-xs uppercase text-slate-400"><?=sanitize($c['category'])?></p><p class="font-bold mt-2"><?=money($c['total'])?></p></div><?php endforeach?></div><section class="card mt-5 overflow-x-auto"><table class="data-table w-full"><thead><tr><th>Date</th><th>Category</th><th>Amount</th><th>Description</th><th>Added by</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d M Y',strtotime($r['expense_date']))?></td><td class="capitalize"><?=sanitize($r['category'])?></td><td class="text-orange-300"><?=money($r['amount'])?></td><td><?=sanitize($r['description'])?></td><td><?=sanitize($r['user_name'])?></td></tr><?php endforeach?></tbody></table></section><div class="card mt-5 border-emerald-500/40"><p class="text-slate-400">Net Profit This Month</p><p class="text-3xl font-bold mt-1 <?=($revenue-$expenseTotal)>=0?'text-emerald-400':'text-red-400'?>"><?=money($revenue-$expenseTotal)?></p><p class="text-xs text-slate-500 mt-2">Revenue <?=money($revenue)?> − Expenses <?=money($expenseTotal)?></p></div><?php require __DIR__.'/../includes/footer.php'; ?>
